pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 i) public {
        // The two offsets are 0 and 0x14. The fuzzer picks an index; we use it
        // to decide which address to read: 0 -> owner, 1 -> any other, which
        // when re-mapped gives 0x14 for i >= 1.
        uint256 offset = i == 0 ? 0 : 0x14;
        // Even though the contract uses _getArgAddress internally, we only
        // need the invariant on the public owner() return. The invariant is:
        //   owner() != _getArgAddress(collateral)
        // We cannot call _getArgAddress directly (it's internal).  But we can
        // derive both values from their public getters: owner() returns offset
        // 0 in the reference, offset 0x14 in the mutant.  The collateral getter
        // always returns offset 0x14.  So reading c.owner() and c.collateral()
        // is enough to witness the difference.
        assertTrue(c.owner() != c.collateral());
    }
}

