pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, CoolerFactory} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    CoolerFactory factory;

    function setUp() public {
        factory = new CoolerFactory();
    }

    function testFuzz_property(address owner_, address collateral_, address debt_) public {
        // Ensure addresses are distinct and non-zero
        vm.assume(owner_ != address(0));
        vm.assume(collateral_ != address(0));
        vm.assume(debt_ != address(0));
        vm.assume(owner_ != collateral_);
        vm.assume(owner_ != debt_);
        vm.assume(collateral_ != debt_);

        // Create a mock ERC20 with a decimals() view to satisfy the factory's internal calls
        // We don't need a full ERC20; just a contract that returns 18 for decimals()
        MockERC20 coll = new MockERC20("Collateral", "COL", 18);
        MockERC20 debt = new MockERC20("Debt", "DEBT", 18);

        address coolerAddress;
        vm.prank(owner_);
        try factory.generateCooler(ERC20(address(coll)), ERC20(address(debt))) returns (address _cooler) {
            coolerAddress = _cooler;
        } catch {
            // May fail if collateral/debt don't implement ERC20 (but we use mocks)
            return;
        }

        c = C(coolerAddress);

        // The owner() call is pure; no gas/state issues
        address returnedOwner = c.owner();

        // The invariant: owner() must equal the original factory caller (owner_)
        // The buggy version reads offset 0x28 (debt token) and will differ.
        assertTrue(returnedOwner == owner_, "owner mismatch");
    }
}

contract MockERC20 {
    string public name;
    string public symbol;
    uint8 public decimals;

    constructor(string memory _name, string memory _symbol, uint8 _decimals) {
        name = _name;
        symbol = _symbol;
        decimals = _decimals;
    }
}

interface ERC20 {
    function decimals() external view returns (uint8);
}

